 55→// EnsureSetup ensures the strategy is properly set up.
 56→func EnsureSetup(ctx context.Context) error {
 57→	if err := EnsureEntireGitignore(ctx); err != nil {
 58→		return err
 59→	}
 60→
 61→	// Ensure the entire/checkpoints/v1 orphan branch exists for permanent session storage
 62→	repo, err := OpenRepository(ctx)
 63→	if err != nil {
 64→		return fmt.Errorf("failed to open git repository: %w", err)
 65→	}
 66→	if err := EnsureMetadataBranch(repo); err != nil {
 67→		return fmt.Errorf("failed to ensure metadata branch: %w", err)
 68→	}
 69→
 70→	// Install generic hooks (they delegate to strategy at runtime)
 71→	if !IsGitHookInstalled(ctx) {
 72→		if _, err := InstallGitHook(ctx, true, isLocalDev(ctx)); err != nil {
 73→			return fmt.Errorf("failed to install git hooks: %w", err)
 74→		}
 75→	}
 76→	return nil
 77→}
