 79→// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
 80→// Returns true if target can reach commit by following parent links.
 81→// Limits search to MaxCommitTraversalDepth commits to avoid excessive traversal.
 82→func IsAncestorOf(repo *git.Repository, commit, target plumbing.Hash) bool {
 83→	if commit == target {
 84→		return true
 85→	}
 86→
 87→	iter, err := repo.Log(&git.LogOptions{From: target})
 88→	if err != nil {
 89→		return false
 90→	}
 91→	defer iter.Close()
 92→
 93→	found := false
 94→	count := 0
 95→	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
 96→		count++
 97→		if count > MaxCommitTraversalDepth {
 98→			return errStop
 99→		}
100→		if c.Hash == commit {
101→			found = true
102→			return errStop
103→		}
104→		return nil
105→	})
106→
107→	return found
108→}
