110→// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
111→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
112→func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
113→	repo, err := OpenRepository(ctx)
114→	if err != nil {
115→		return nil, fmt.Errorf("failed to open git repository: %w", err)
116→	}
117→
118→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
119→	ref, err := repo.Reference(refName, true)
120→	if err != nil {
121→		//nolint:nilerr // No sessions branch yet is expected, return empty list
122→		return []CheckpointInfo{}, nil
123→	}
124→
125→	commit, err := repo.CommitObject(ref.Hash())
126→	if err != nil {
127→		return nil, fmt.Errorf("failed to get commit object: %w", err)
128→	}
129→
130→	tree, err := commit.Tree()
131→	if err != nil {
132→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
133→	}
134→
135→	var checkpoints []CheckpointInfo
136→
137→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
138→	// The tree has 2-character directories (hex buckets)
139→	for _, bucketEntry := range tree.Entries {
140→		if bucketEntry.Mode != filemode.Dir {
141→			continue
142→		}
143→		// Bucket should be 2 hex chars
144→		if len(bucketEntry.Name) != 2 {
145→			continue
146→		}
147→
148→		bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
149→		if treeErr != nil {
150→			continue
151→		}
152→
153→		// Each entry in the bucket is the remaining part of the checkpoint ID
154→		for _, checkpointEntry := range bucketTree.Entries {
155→			if checkpointEntry.Mode != filemode.Dir {
156→				continue
157→			}
158→
159→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
160→			if cpTreeErr != nil {
161→				continue
162→			}
163→
164→			// Reconstruct checkpoint ID: <bucket><remaining>
165→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
166→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
167→			if cpErr != nil {
168→				// Skip invalid checkpoint IDs
169→				continue
170→			}
171→
172→			info := CheckpointInfo{
173→				CheckpointID: checkpointID,
174→			}
175→
176→			// Get details from metadata file (CheckpointSummary format)
177→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
178→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
179→					var summary checkpoint.CheckpointSummary
180→					if json.Unmarshal([]byte(content), &summary) == nil && len(summary.Sessions) > 0 {
181→						info.CheckpointsCount = summary.CheckpointsCount
182→						info.FilesTouched = summary.FilesTouched
183→						info.SessionCount = len(summary.Sessions)
184→
185→						// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
186→						for i, sessionPaths := range summary.Sessions {
187→							if sessionPaths.Metadata != "" {
188→								// SessionFilePaths now contains absolute paths with leading "/"
189→								// Strip the leading "/" for tree.File() which expects paths without leading slash
190→								sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
191→								if sessionFile, sErr := tree.File(sessionMetadataPath); sErr == nil {
192→									if sessionContent, scErr := sessionFile.Contents(); scErr == nil {
193→										var sessionMetadata checkpoint.CommittedMetadata
194→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
195→											info.SessionIDs = append(info.SessionIDs, sessionMetadata.SessionID)
196→											// Use first session's metadata for Agent, SessionID, CreatedAt
197→											if i == 0 {
198→												info.Agent = sessionMetadata.Agent
199→												info.SessionID = sessionMetadata.SessionID
200→												info.CreatedAt = sessionMetadata.CreatedAt
201→												info.IsTask = sessionMetadata.IsTask
202→												info.ToolUseID = sessionMetadata.ToolUseID
203→											}
204→										}
205→									}
206→								}
207→							}
208→						}
209→					}
210→				}
211→			}
212→
213→			checkpoints = append(checkpoints, info)
214→		}
215→	}
216→
217→	// Sort by time (most recent first)
218→	sort.Slice(checkpoints, func(i, j int) bool {
219→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
220→	})
221→
222→	return checkpoints, nil
223→}
