235→// isProtectedPath returns true if relPath is inside a directory that should
236→// never be modified or deleted during rewind or other destructive operations.
237→// Protected directories include git internals, entire metadata, and all
238→// registered agent config directories.
239→func isProtectedPath(relPath string) bool {
240→	for _, dir := range protectedDirs() {
241→		if relPath == dir || strings.HasPrefix(relPath, dir+string(filepath.Separator)) {
242→			return true
243→		}
244→	}
245→	return false
246→}
